def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the horizontal pattern period in the regular lower portion.
    best_p = 1
    best_score = float("inf")
    for p in range(1, 13):
        matches = mismatches = 0
        for r in range(8, h):
            for c in range(3, w - p):
                a, b = grid[r][c], grid[r][c + p]
                if a and b:
                    matches += 1
                    mismatches += (a != b)
        score = mismatches / matches if matches else float("inf")
        if (score, p) < (best_score, best_p):
            best_score, best_p = score, p
    p = best_p

    # Get one full cycle from the longest uninterrupted lower-row segment.
    best_run = []
    run_start = 3
    for r in range(8, h):
        c = 3
        while c < w:
            start = c
            while c < w and grid[r][c] != 0:
                c += 1
            if c - start > len(best_run):
                best_run = grid[r][start:c]
                run_start = start
            c += 1

    if len(best_run) < p:
        return [row[:] for row in grid]
    cycle = best_run[:p]

    out = [row[:] for row in grid]
    for r in range(h):
        # Determine this row's phase by matching its visible pattern cells.
        best_offset, best_count = 0, -1
        for offset in range(p):
            count = 0
            for c in range(3, w):
                value = grid[r][c]
                if value in cycle and value == cycle[(c - run_start + offset) % p]:
                    count += 1
            if count > best_count:
                best_offset, best_count = offset, count

        for c in range(w):
            if grid[r][c] != 0:
                continue
            if r < 2 or c < 2:
                out[r][c] = 1
            elif r == 2 or c == 2:
                out[r][c] = 4
            else:
                out[r][c] = cycle[(c - run_start + best_offset) % p]

    return out
